pub fn recordConstructorDef(mut txt: Tpl::Text, mut a_ctor__name: ArcStr, mut a_rec__name: ArcStr, mut a_variables: Arc<metamodelica::List<Arc<SimCodeFunction::Variable::Variable>>>) -> Result<Tpl::Text> {
    let mut out_txt: Tpl::Text;
    let mut l_varInits: Tpl::Text;
    let mut l_ctor__additional__inputs: Tpl::Text;
    let mut l_auxFunction: Tpl::Text;
    let mut l_varDecls: Tpl::Text;
    l_varDecls = Tpl::emptyTxt.clone();
    l_auxFunction = Tpl::emptyTxt.clone();
    (l_ctor__additional__inputs, l_auxFunction) = lm_132(Tpl::emptyTxt.clone(), a_variables.clone(), l_auxFunction.clone())?;
    (l_varInits, l_auxFunction, l_varDecls) = lm_133(Tpl::emptyTxt.clone(), a_variables.clone(), l_auxFunction.clone(), l_varDecls.clone())?;
    out_txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING { value: (literal!("void ")).clone() }))?;
    out_txt = Tpl::writeStr(out_txt.clone(), (a_ctor__name.clone()).clone())?;
    out_txt = Tpl::writeTok(out_txt.clone(), Arc::new(Tpl::StringToken::ST_STRING { value: (literal!("_construct_p(threadData_t *threadData, void* v_ths ")).clone() }))?;
    out_txt = Tpl::writeText(out_txt.clone(), l_ctor__additional__inputs.clone())?;
    out_txt = Tpl::writeTok(out_txt.clone(), Arc::new(Tpl::StringToken::ST_LINE { line: (literal!(") {\n")).clone() }))?;
    out_txt = Tpl::pushBlock(out_txt.clone(), Arc::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
    out_txt = Tpl::writeStr(out_txt.clone(), (a_rec__name.clone()).clone())?;
    out_txt = Tpl::writeTok(out_txt.clone(), Arc::new(Tpl::StringToken::ST_STRING { value: (literal!("* ths = (")).clone() }))?;
    out_txt = Tpl::writeStr(out_txt.clone(), (a_rec__name.clone()).clone())?;
    out_txt = Tpl::writeTok(out_txt.clone(), Arc::new(Tpl::StringToken::ST_LINE { line: (literal!("*)(v_ths);\n")).clone() }))?;
    out_txt = Tpl::writeText(out_txt.clone(), l_varDecls.clone())?;
    out_txt = Tpl::softNewLine(out_txt.clone())?;
    out_txt = Tpl::writeText(out_txt.clone(), l_varInits.clone())?;
    out_txt = Tpl::softNewLine(out_txt.clone())?;
    out_txt = Tpl::popBlock(out_txt.clone())?;
    out_txt = Tpl::writeTok(out_txt.clone(), Arc::new(Tpl::StringToken::ST_STRING { value: (literal!("}")).clone() }))?;
    Ok(out_txt)
}

